{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required input field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    ids = set()
    by_id = {}
    root_ids = []
    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in required_node_fields:
            if field not in node:
                raise ValueError("node missing required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id in ids:
            raise ValueError("node ids must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            raise ValueError("utility must be numeric")

        ids.add(node_id)
        by_id[node_id] = node
        if parent is None:
            root_ids.append(node_id)

    if len(root_ids) != 1:
        raise ValueError("there must be exactly one root")

    root_id = root_ids[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("parent id not found")
        expected_depth = by_id[parent]["depth"] + 1
        if node["depth"] != expected_depth:
            raise ValueError("node depth is inconsistent with parent")
        children[parent].append(node_id)

    initial_symbols = {node["symbol"] for node in nodes}
    for symbol in required_symbols:
        if symbol not in initial_symbols:
            raise ValueError("required symbol is not represented")

    retained = {node["id"] for node in nodes}
    removed = []
    required_set = set(required_symbols)

    candidates = sorted(
        nodes,
        key=lambda node: (-node["depth"], node["id"]),
    )

    for node in candidates:
        node_id = node["id"]
        if node_id == root_id:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required_set:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        tentative = retained - {node_id}
        represented = {by_id[retained_id]["symbol"] for retained_id in tentative}
        if all(symbol in represented for symbol in required_symbols):
            retained = tentative
            removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
